import Foundation

func fetchData(url: URL) {
    let task = URLSession.shared.dataTask(with: url) { data, response, error in
        if let error = error {
            print("Error fetching data: \(error)")
            return
        }

        guard let data = data else {
            print("No data received")
            return
        }

        // Process the fetched data here
        print("Fetched Data: \(String(data: data, encoding: .utf8)!))
    }

    task.resume()
}

// Example usage:
let urlString = "https://example.com/api/data"
fetchData(url: URL(string: urlString)!)
```

In this example, we're using `URLSession` to make an asynchronous request to a web API. The `dataTask` method is used to handle the incoming data, which is then processed in the `processData` function.

This approach allows you to avoid capturing the user's device ID (which could reveal your location), as it uses the network for data transfer instead of storing it locally.

